const enc = new TextEncoder();
const COOKIE = 'ahmed_admin';

function b64(bytes){ let s=''; for(const b of bytes) s+=String.fromCharCode(b); return btoa(s).replaceAll('+','-').replaceAll('/','_').replaceAll('=',''); }
function unb64(s){ s=s.replaceAll('-','+').replaceAll('_','/'); while(s.length%4)s+='='; const bin=atob(s); return Uint8Array.from(bin,c=>c.charCodeAt(0)); }
async function key(secret){ return crypto.subtle.importKey('raw',enc.encode(secret),{name:'HMAC',hash:'SHA-256'},false,['sign','verify']); }
async function sign(value,secret){ return b64(new Uint8Array(await crypto.subtle.sign('HMAC',await key(secret),enc.encode(value)))); }
async function makeCookie(secret){ const value=`${Date.now()}.${crypto.randomUUID()}`; return `${value}.${await sign(value,secret)}`; }
async function validCookie(request,secret){ if(!secret)return false; const m=request.headers.get('Cookie')?.match(new RegExp(`${COOKIE}=([^;]+)`)); if(!m)return false; const parts=m[1].split('.'); if(parts.length<3)return false; const value=parts.slice(0,2).join('.'); const ts=Number(parts[0]); if(!Number.isFinite(ts)||Date.now()-ts>1000*60*60*24*7)return false; return crypto.subtle.verify('HMAC',await key(secret),unb64(parts[2]),enc.encode(value)); }
function setCookie(value){return `${COOKIE}=${value}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=604800`}
function clearCookie(){return `${COOKIE}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`}
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json;charset=utf-8','cache-control':'no-store'}})}
