const COLLECTIONS={projects:{table:'projects',fields:PROJECT_FIELDS,required:'title_en'},videos:{table:'videos',fields:VIDEO_FIELDS,required:'title_en'},skills:{table:'skills',fields:SKILL_FIELDS,required:'name_en'},certs:{table:'certifications',fields:CERT_FIELDS,required:'name_en'},services:{table:'services',fields:SERVICE_FIELDS,required:'title_en'},approach:{table:'approach_steps',fields:APPROACH_FIELDS,required:'title_en'},navigation:{table:'navigation',fields:NAV_FIELDS,required:'label_en'},sections:{table:'custom_sections',fields:SECTION_FIELDS,required:'title_en'}};

async function collectionApi(request,env,kind){ const isAdmin=await validCookie(request,env.ADMIN_SECRET); const c=COLLECTIONS[kind]; if(!c)return json({error:'Not Found'},404); if(request.method==='GET'){ const q=isAdmin?`SELECT * FROM ${c.table} ORDER BY sort_order ASC,id ASC`:`SELECT * FROM ${c.table} WHERE published=1 ORDER BY sort_order ASC,id ASC`; const {results}=await env.DB.prepare(q).all(); return json(results||[]); } if(!isAdmin)return json({error:'غير مصرح'},401); if(request.method==='POST'){let body;try{body=await request.json()}catch{return json({error:'JSON غير صالح'},400)}const d=clean(body,c.fields);if(!d.slug||!d[c.required])return json({error:'Slug والاسم الأساسي مطلوبان'},400);try{const r=await env.DB.prepare(`INSERT INTO ${c.table} (${Object.keys(d).join(',')}) VALUES (${Object.keys(d).map(()=>'?').join(',')})`).bind(...Object.values(d)).run();return json({id:r.meta.last_row_id,...d},201)}catch(e){return json({error:String(e.message||e)},400)}} if(request.method==='PUT'){let body;try{body=await request.json()}catch{return json({error:'JSON غير صالح'},400)}const id=Number(body.id);if(!id)return json({error:'ID مطلوب'},400);const d=clean(body,c.fields);delete d.id;if(!Object.keys(d).length)return json({error:'لا توجد تغييرات'},400);try{const r=await env.DB.prepare(`UPDATE ${c.table} SET ${Object.keys(d).map(k=>`${k}=?`).join(',')} WHERE id=?`).bind(...Object.values(d),id).run();return json({ok:!!r.meta.changes})}catch(e){return json({error:String(e.message||e)},400)}} if(request.method==='DELETE'){const id=Number(new URL(request.url).searchParams.get('id'));if(!id)return json({error:'ID مطلوب'},400);const r=await env.DB.prepare(`DELETE FROM ${c.table} WHERE id=?`).bind(id).run();return json({ok:!!r.meta.changes})} return json({error:'Method Not Allowed'},405); }

async function toolsApi(request,env){
  const isAdmin=await validCookie(request,env.ADMIN_SECRET);
  if(!isAdmin)return json({error:'غير مصرح'},401);
  if(request.method==='GET'){const {results}=await env.DB.prepare('SELECT * FROM admin_tools ORDER BY sort_order ASC,id ASC').all();return json(results||[])}
  if(request.method==='POST'){let body;try{body=await request.json()}catch{return json({error:'JSON غير صالح'},400)}const d=clean(body,TOOL_FIELDS);if(!d.slug||!d.name_en||!d.url)return json({error:'Slug واسم الأداة والرابط مطلوبون'},400);try{const r=await env.DB.prepare(`INSERT INTO admin_tools (${Object.keys(d).join(',')}) VALUES (${Object.keys(d).map(()=>'?').join(',')})`).bind(...Object.values(d)).run();return json({id:r.meta.last_row_id,...d},201)}catch(e){return json({error:String(e.message||e)},400)}}
  if(request.method==='PUT'){let body;try{body=await request.json()}catch{return json({error:'JSON غير صالح'},400)}const id=Number(body.id);if(!id)return json({error:'ID مطلوب'},400);const d=clean(body,TOOL_FIELDS);delete d.id;if(!Object.keys(d).length)return json({error:'لا توجد تغييرات'},400);try{const r=await env.DB.prepare(`UPDATE admin_tools SET ${Object.keys(d).map(k=>`${k}=?`).join(',')} WHERE id=?`).bind(...Object.values(d),id).run();return json({ok:!!r.meta.changes})}catch(e){return json({error:String(e.message||e)},400)}}
  if(request.method==='DELETE'){const id=Number(new URL(request.url).searchParams.get('id'));if(!id)return json({error:'ID مطلوب'},400);const r=await env.DB.prepare('DELETE FROM admin_tools WHERE id=?').bind(id).run();return json({ok:!!r.meta.changes})}
  return json({error:'Method Not Allowed'},405);
}

async function settingsApi(request,env){ const isAdmin=await validCookie(request,env.ADMIN_SECRET); if(request.method==='GET'){const {results}=await env.DB.prepare('SELECT key,en,ar FROM site_settings ORDER BY key').all();return json(results||[]);} if(!isAdmin)return json({error:'غير مصرح'},401); if(request.method==='PUT'){let b;try{b=await request.json()}catch{return json({error:'JSON غير صالح'},400)} const items=Array.isArray(b)?b:(b.items||[]); if(!items.length)return json({error:'لا توجد تغييرات'},400); const stmts=[]; for(const x of items){if(!x.key)continue;stmts.push(env.DB.prepare('INSERT INTO site_settings (key,en,ar) VALUES (?,?,?) ON CONFLICT(key) DO UPDATE SET en=excluded.en,ar=excluded.ar').bind(String(x.key),String(x.en??''),String(x.ar??'')));} if(stmts.length)await env.DB.batch(stmts);return json({ok:true});} return json({error:'Method Not Allowed'},405); }

async function api(request,env){ const url=new URL(request.url); if(url.pathname==='/api/login'&&request.method==='POST'){let b;try{b=await request.json()}catch{return json({error:'بيانات غير صالحة'},400)}if(!env.ADMIN_USERNAME||!env.ADMIN_PASSWORD)return json({error:'بيانات دخول الأدمن غير مكتملة في Cloudflare'},500);if(b.username!==env.ADMIN_USERNAME||b.password!==env.ADMIN_PASSWORD)return json({error:'اسم المستخدم أو كلمة المرور غير صحيحة'},401);if(!env.ADMIN_SECRET)return json({error:'ADMIN_SECRET غير مضبوط في Cloudflare'},500);const c=await makeCookie(env.ADMIN_SECRET);return new Response(JSON.stringify({ok:true}),{headers:{'content-type':'application/json','set-cookie':setCookie(c)}});} if(url.pathname==='/api/logout'&&request.method==='POST')return new Response(JSON.stringify({ok:true}),{headers:{'content-type':'application/json','set-cookie':clearCookie()}}); if(url.pathname==='/api/me'&&request.method==='GET')return json({authenticated:await validCookie(request,env.ADMIN_SECRET)}); await ensureTables(env); if(url.pathname==='/api/tools')return toolsApi(request,env); if(url.pathname==='/api/settings')return settingsApi(request,env); if(request.method==='GET'&&/^\/api\/projects\/[^/]+$/.test(url.pathname)){const slug=decodeURIComponent(url.pathname.split('/').pop()||''); const isAdmin=await validCookie(request,env.ADMIN_SECRET); const row=await env.DB.prepare(isAdmin?'SELECT * FROM projects WHERE slug=?':'SELECT * FROM projects WHERE slug=? AND published=1').bind(slug).first(); return row?json(row):json({error:'Project Not Found'},404);} const map={'/api/projects':'projects','/api/videos':'videos','/api/skills':'skills','/api/certifications':'certs','/api/services':'services','/api/approach':'approach','/api/navigation':'navigation','/api/sections':'sections'}; if(map[url.pathname])return collectionApi(request,env,map[url.pathname]); if(url.pathname==='/api/posts'){const isAdmin=await validCookie(request,env.ADMIN_SECRET);if(request.method==='GET'){const q=isAdmin?'SELECT * FROM posts ORDER BY sort_order ASC,id ASC':'SELECT * FROM posts WHERE published=1 ORDER BY sort_order ASC,id ASC';const {results}=await env.DB.prepare(q).all();return json(results||[])}if(!isAdmin)return json({error:'غير مصرح'},401);if(request.method==='POST'){let body;try{body=await request.json()}catch{return json({error:'JSON غير صالح'},400)}const d=clean(body,POST_FIELDS);if(!d.slug||!d.title_en)return json({error:'Slug و Title EN مطلوبان'},400);try{const r=await env.DB.prepare(`INSERT INTO posts (${Object.keys(d).join(',')}) VALUES (${Object.keys(d).map(()=>'?').join(',')})`).bind(...Object.values(d)).run();return json({id:r.meta.last_row_id,...d},201)}catch(e){return json({error:String(e.message||e)},400)}}if(request.method==='PUT'){let body;try{body=await request.json()}catch{return json({error:'JSON غير صالح'},400)}const id=Number(body.id);if(!id)return json({error:'ID مطلوب'},400);const d=clean(body,POST_FIELDS);delete d.id;if(!Object.keys(d).length)return json({error:'لا توجد تغييرات'},400);try{const r=await env.DB.prepare(`UPDATE posts SET ${Object.keys(d).map(k=>`${k}=?`).join(',')} WHERE id=?`).bind(...Object.values(d),id).run();return json({ok:!!r.meta.changes})}catch(e){return json({error:String(e.message||e)},400)}}if(request.method==='DELETE'){const id=Number(url.searchParams.get('id'));if(!id)return json({error:'ID مطلوب'},400);const r=await env.DB.prepare('DELETE FROM posts WHERE id=?').bind(id).run();return json({ok:!!r.meta.changes})}} return json({error:'Not Found'},404); }

function htmlEsc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function absoluteAssetUrl(value,origin){
  const v=String(value||'').trim();
  if(!v) return '';
  try{return new URL(v,origin+'/').href;}catch{return '';}
}

async function projectPage(request,env,url){
  const slug=decodeURIComponent(url.pathname.split('/').filter(Boolean).pop()||'');
  if(!slug) return Response.redirect(new URL('/',url),302);
  let row;
  try{ row=await env.DB.prepare('SELECT * FROM projects WHERE slug=? AND published=1').bind(slug).first(); }
  catch(e){ try{ await ensureTables(env); row=await env.DB.prepare('SELECT * FROM projects WHERE slug=? AND published=1').bind(slug).first(); }catch(_){} }
  if(!row) return new Response('Project Not Found',{status:404,headers:{'content-type':'text/plain;charset=utf-8','cache-control':'no-store'}});

  const title=String(row.title_en||row.title_ar||'Project');
  const description=String(row.desc_en||row.desc_ar||'Financial analysis and modeling project by Ahmed Elsheshtawy.');
  const canonical=url.origin+'/project/'+encodeURIComponent(slug);
  const socialImage=url.origin+'/assets/social/'+encodeURIComponent(slug)+'.png';
  const esc=htmlEsc;
  const text=(en,ar)=>String(en||ar||'');
  const splitUrls=(v)=>String(v||'').split(/\r?\n|,/).map(x=>x.trim()).filter(Boolean);
  const isImage=(u)=>/\.(png|jpe?g|webp|gif|svg|avif)(?:[?#].*)?$/i.test(String(u||''));
  const fileName=(u)=>{try{return decodeURIComponent(new URL(u,url.origin).pathname.split('/').pop()||'File')}catch{return String(u||'').split('/').pop()||'File'}};
  const fileType=(u)=>{const n=fileName(u).toLowerCase();if(/\.xlsx?$/.test(n))return 'Excel';if(/\.pdf$/.test(n))return 'PDF';if(/\.pptx?$/.test(n))return 'PowerPoint';if(/\.docx?$/.test(n))return 'Word';if(/\.(zip|rar|7z)$/.test(n))return 'Archive';return 'File'};
  const abs=(u)=>absoluteAssetUrl(u,url.origin);
  let modelImages=[],dashImages=[],modelFiles=[],dashFiles=[];
  splitUrls(row.model_url).forEach(u=>(isImage(u)?modelImages:modelFiles).push(u));
  splitUrls(row.model_gallery).forEach(u=>(isImage(u)?modelImages:modelFiles).push(u));
  splitUrls(row.model_images).forEach(u=>modelImages.push(u));
  splitUrls(row.model_files).forEach(u=>modelFiles.push(u));
  splitUrls(row.dashboard_url).forEach(u=>(isImage(u)?dashImages:dashFiles).push(u));
  splitUrls(row.dashboard_gallery).forEach(u=>(isImage(u)?dashImages:dashFiles).push(u));
  splitUrls(row.dashboard_images).forEach(u=>dashImages.push(u));
  splitUrls(row.dashboard_files).forEach(u=>dashFiles.push(u));
  modelImages=[...new Set(modelImages)].filter(Boolean); dashImages=[...new Set(dashImages)].filter(Boolean);
  modelFiles=[...new Set(modelFiles)].filter(Boolean); dashFiles=[...new Set(dashFiles)].filter(Boolean);
  let modelParts=[],dashParts=[];
  try{modelParts=JSON.parse(row.model_parts||'[]')||[]}catch(_){}
  try{dashParts=JSON.parse(row.dashboard_parts||'[]')||[]}catch(_){}
  let image='';
  for(const c of [...modelImages,...dashImages]){const u=abs(c);if(u){image=u;break;}}
  if(!image) image=url.origin+'/assets/profile.png';

  const panels=[];
  function imagePanel(kind,u,name){return `<div class="case-panel"><div class="panel-head"><span>${esc(name)}</span><b>${kind}</b></div><div class="asset"><img src="${esc(abs(u))}" alt="${esc(name)}" loading="lazy"></div></div>`}
  if(modelParts.length){modelParts.forEach((x,i)=>{const n=text(x.name_en,x.name_ar)||`Model ${i+1}`; if(x.image_url)panels.push(imagePanel('MODEL',x.image_url,n));});}
  else modelImages.forEach((u,i)=>panels.push(imagePanel('MODEL',u,`Financial Model${modelImages.length>1?' · '+(i+1):''}`)));
  if(dashParts.length){dashParts.forEach((x,i)=>{const n=text(x.name_en,x.name_ar)||`Dashboard ${i+1}`; if(x.image_url)panels.push(imagePanel('DASHBOARD',x.image_url,n));});}
  else dashImages.forEach((u,i)=>panels.push(imagePanel('DASHBOARD',u,`Analysis Dashboard${dashImages.length>1?' · '+(i+1):''}`)));
  if(!panels.length) panels.push(`<div class="case-panel empty-panel"><div class="panel-head"><span>CASE STUDY</span><b>PROJECT</b></div><div class="asset empty"><span>No preview image available</span></div></div>`);
  const files=[...modelFiles.map(u=>({u,k:'MODEL FILE'})),...dashFiles.map(u=>({u,k:'DASHBOARD FILE'}))];
  const fileHtml=files.length?`<div class="files">${files.map(f=>`<a href="${esc(abs(f.u))}" target="_blank" rel="noopener"><span class="file-icon">↗</span><span><strong>${esc(fileName(f.u))}</strong><small>${esc(f.k)} · ${esc(fileType(f.u))}</small></span></a>`).join('')}</div>`:'';
  const projectHtml=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} — Ahmed Elsheshtawy</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${esc(canonical)}"><meta property="og:type" content="website"><meta property="og:site_name" content="Ahmed Elsheshtawy — Financial Analyst"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${esc(canonical)}"><meta property="og:image" content="${esc(socialImage)}"><meta property="og:image:secure_url" content="${esc(socialImage)}"><meta property="og:image:type" content="image/png"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="627"><meta property="og:image:alt" content="${esc(title)}"><meta property="og:locale" content="en_US"><meta name="author" content="Ahmed Elsheshtawy"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(description)}"><meta name="twitter:image" content="${esc(socialImage)}"><link rel="icon" href="/assets/logo-loader.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Inter:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet"><style>
:root{--bg:#f4f2ec;--ink:#151515;--soft:#66615a;--accent:#ff4d00;--line:#ddd8cc;--dark:#0b0b0b;--white:#fff}*{box-sizing:border-box}html,body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,Arial,sans-serif}body{min-height:100vh}.page{max-width:1180px;margin:0 auto;padding:56px 34px 80px}.top{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:34px}.back{font:500 11px 'IBM Plex Mono',monospace;text-transform:uppercase;letter-spacing:.08em;text-decoration:none;color:var(--soft)}.brand{font:700 14px 'Space Grotesk',sans-serif}.kicker{font:500 11px 'IBM Plex Mono',monospace;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);margin-bottom:10px}.title{font:700 clamp(38px,6vw,72px) 'Space Grotesk',sans-serif;line-height:.98;letter-spacing:-.05em;max-width:900px;margin:0 0 22px}.desc{font-size:17px;line-height:1.65;color:var(--soft);max-width:760px;margin:0 0 28px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:38px}.btn{border:1px solid var(--line);border-radius:999px;padding:11px 16px;text-decoration:none;color:var(--ink);font:600 12px 'IBM Plex Mono',monospace;background:#faf9f5;cursor:pointer}.btn:hover{border-color:var(--accent)}.btn.primary{background:var(--ink);color:#fff;border-color:var(--ink)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-bottom:40px}.case-panel{background:var(--dark);border:1px solid #252525;border-radius:18px;overflow:hidden;min-height:330px}.panel-head{height:48px;padding:0 16px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #292929;color:#fff}.panel-head span{font:500 10px 'IBM Plex Mono',monospace;letter-spacing:.08em;color:#aaa;text-transform:uppercase}.panel-head b{font:500 10px 'IBM Plex Mono',monospace;color:var(--accent);font-weight:500}.asset{min-height:282px;background:#101010;display:flex;align-items:center;justify-content:center;overflow:hidden}.asset img{width:100%;height:100%;min-height:282px;object-fit:contain;padding:10px}.empty{color:#8a8a8a;font:500 11px 'IBM Plex Mono',monospace}.files{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:0 0 40px}.files a{display:flex;align-items:center;gap:12px;background:#101010;color:#fff;border:1px solid #292929;border-radius:16px;padding:14px;text-decoration:none}.files a:hover{border-color:var(--accent)}.file-icon{width:40px;height:40px;border-radius:10px;background:#1c1c1c;display:grid;place-items:center;color:var(--accent);flex:0 0 40px}.files strong{display:block;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:420px}.files small{display:block;color:#888;font:500 9px 'IBM Plex Mono',monospace;margin-top:4px;text-transform:uppercase}.content{display:grid;grid-template-columns:1fr 1fr;gap:36px;border-top:1px solid var(--line);padding-top:36px}.section{margin-bottom:24px}.section h2{font:700 13px 'IBM Plex Mono',monospace;letter-spacing:.05em;text-transform:uppercase;color:var(--accent);margin:0 0 9px}.section p{font-size:16px;line-height:1.7;color:var(--soft);margin:0}.footer{border-top:1px solid var(--line);margin-top:44px;padding-top:22px;color:#999;font:500 10px 'IBM Plex Mono',monospace}@media(max-width:760px){.page{padding:30px 18px 55px}.grid,.content,.files{grid-template-columns:1fr}.title{font-size:42px}.top{margin-bottom:28px}.desc{font-size:15px}.case-panel{min-height:260px}.asset,.asset img{min-height:212px}}
</style></head><body><main class="page"><div class="top"><a class="back" href="/">← Back to portfolio</a><div class="brand">AHMED ELSHESHTAWY</div></div><div class="kicker">${esc(text(row.cat_en,row.cat_ar)||'Financial Analysis · Case Study')}</div><h1 class="title">${esc(title)}</h1><p class="desc">${esc(description)}</p><div class="actions"><button class="btn primary" id="copy">Copy project link</button><a class="btn" href="/">View portfolio</a></div><div class="grid">${panels.join('')}</div>${fileHtml}<div class="content"><div>${[['Overview',row.overview_en,row.overview_ar],['Business Problem',row.problem_en,row.problem_ar],['Objective',row.objective_en,row.objective_ar],['Data & Assumptions',row.data_en,row.data_ar]].map(x=>`<section class="section"><h2>${x[0]}</h2><p>${esc(text(x[1],x[2]))}</p></section>`).join('')}</div><div>${[['Analysis',row.analysis_en,row.analysis_ar],['Key Findings',row.findings_en,row.findings_ar],['Lessons Learned',row.lessons_en,row.lessons_ar]].map(x=>`<section class="section"><h2>${x[0]}</h2><p>${esc(text(x[1],x[2]))}</p></section>`).join('')}</div></div><div class="footer">© 2026 Ahmed Elsheshtawy · Financial Analyst · Financial Modeling · FP&A</div></main><script>document.getElementById('copy').addEventListener('click',async function(){try{await navigator.clipboard.writeText(${JSON.stringify(canonical)});this.textContent='✓ Link copied';setTimeout(()=>this.textContent='Copy project link',1800)}catch(e){prompt('Copy this project link:',${JSON.stringify(canonical)})}});</script></body></html>`;
  return new Response(projectHtml,{status:200,headers:{'content-type':'text/html;charset=utf-8','cache-control':'public,max-age=300','x-robots-tag':'index,follow'}});
}

export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname.startsWith('/api/'))return api(request,env);if(request.method==='GET'&&/^\/project\/[^/]+\/?$/.test(url.pathname))return projectPage(request,env,url);return env.ASSETS.fetch(request);}};
